Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='fixturepins', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title='A test that only the fixture build compiles runs with the fixture feature before a pull request is ready', body='The pins under app/cli/tests are compiled only with the cargo feature suzatary/fixture. Before a pull request is ready, run those tests with the flag --features suzatary/fixture. A moved call layout moves every pin, and a build without the feature does not compile the pins, so it cannot show the move.', rationale='A default build and a default clippy run skip these tests, so a change that moves a pin passes them and fails on the train. The deployed build does not compile the feature on purpose, so only a run with the feature shows the pin.', supersedes=()))